/* 
   Task 1: Parcel Intake, Sorting and Processing Module
   Author: [Student Name]
   Description: Implementing a Doubly Linked List for parcel management to allow efficient O(1) removal from anywhere in the list when parcels are 'sorted' or 'routed' to other stages.
*/

#include <iostream>
#include <string>
#include <ctime>
#include <vector>

using namespace std; 

struct Parcel {
    string parcelID;
    string recipientName;
    string type; // e.g., Box, Envelope
    string status; // Pending, In-Sorting, Dispatched, etc.
    string arrivalTime;
    Parcel *next, *prev;

    Parcel(string id, string rec, string t, string s) : parcelID(id), recipientName(rec), type(t), status(s), next(NULL), prev(NULL) {
        time_t now = time(0);
        arrivalTime = ctime(&now);
    }
};

class ParcelIntakeSystem {
private:
    Parcel *head, *tail;
    vector<string> registeredIDs;

public:
    ParcelIntakeSystem() : head(NULL), tail(NULL) {}

    // Requirement 1 & 5: Register and prevent duplicates
    void registerParcel(string id, string rec, string type) {
        if (id == "" || rec == "") { cout << "Error: Missing information.\n"; return; }
        for (string s : registeredIDs) if (s == id) { cout << "Error: Duplicate ID " << id << "\n"; return; }

        Parcel* newParcel = new Parcel(id, rec, type, "Registered");
        if (!head) head = tail = newParcel;
        else { tail->next = newParcel; newParcel->prev = tail; tail = newParcel; }
        registeredIDs.push_back(id);
        cout << "Parcel " << id << " registered successfully.\n";
    }

    // Requirement 2: Search and View
    Parcel* searchParcel(string id) {
        Parcel* curr = head;
        while (curr) {
            if (curr->parcelID == id) return curr;
            curr = curr->next;
        }
        cout << "Error: Parcel " << id << " not found.\n";
        return NULL;
    }

    // Requirement 3 & 4: Sort/Route and Update
    void routeParcel(string id, string action) {
        Parcel* p = searchParcel(id);
        if (!p) return;
        if (p->status == "Completed" || p->status == "Returned") {
            cout << "Error: Cannot process finished parcel.\n";
            return;
        }
        p->status = action;
        cout << "Parcel " << id << " routed for: " << action << "\n";
    }

    void displayAll() {
        if (!head) { cout << "System empty.\n"; return; }
        Parcel* curr = head;
        while (curr) {
            cout << "[" << curr->parcelID << "] " << curr->recipientName << " - Status: " << curr->status << endl;
            curr = curr->next;
        }
    }
};

// Reflection: I chose a Doubly Linked List because during intake, parcels aren't always processed in FIFO order.
// Sometimes a parcel needs urgent sorting (Special Handling), and this structure allows us to remove nodes in O(1)
// if we have the pointer, or easily traverse both ways if we need to audit the 'arrival' history.

/* 
   Task 2: Parcel Service and Collection Management Module
   Author: [Student Name]
   Description: Implementing a Priority Queue (using a Max-Heap array) for service requests. 
   Justification: Urgent requests (Return to Sender, Special Handling) must be prioritized over standard collections.
*/

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

struct ServiceRequest {
    int requestID;
    string parcelID;
    int priority; // 3: Urgent, 2: Standard, 1: Low
    string serviceType;
    string status;
};

class ServiceManager {
private:
    vector<ServiceRequest> heap;

    void heapifyUp(int idx) {
        while (idx > 0 && heap[(idx - 1) / 2].priority < heap[idx].priority) {
            swap(heap[(idx - 1) / 2], heap[idx]);
            idx = (idx - 1) / 2;
        }
    }

    void heapifyDown(int idx) {
        int largest = idx;
        int left = 2 * idx + 1, right = 2 * idx + 2;
        if (left < heap.size() && heap[left].priority > heap[largest].priority) largest = left;
        if (right < heap.size() && heap[right].priority > heap[largest].priority) largest = right;
        if (largest != idx) {
            swap(heap[idx], heap[largest]);
            heapifyDown(largest);
        }
    }

public:
    // Requirement 1: Create Service Request
    void createRequest(int rid, string pid, string type, int prio) {
        for(auto &r : heap) if(r.requestID == rid) { cout << "Duplicate RID\n"; return; }
        ServiceRequest req = {rid, pid, prio, type, "Pending"};
        heap.push_back(req);
        heapifyUp(heap.size() - 1);
        cout << "Request " << rid << " added to queue with priority " << prio << "\n";
    }

    // Requirement 3: Determine Next (Extract Max)
    void processNext() {
        if (heap.empty()) { cout << "No active requests.\n"; return; }
        ServiceRequest top = heap[0];
        cout << "Processing Request " << top.requestID << " (" << top.serviceType << ") for Parcel " << top.parcelID << "\n";
        heap[0] = heap.back();
        heap.pop_back();
        heapifyDown(0);
    }

    void displayRequests() {
        cout << "Active Requests: " << heap.size() << endl;
        for(auto &r : heap) cout << "ID: " << r.requestID << " Prio: " << r.priority << " Type: " << r.serviceType << endl;
    }
};

// Reflection: Using a Priority Queue ensures that students waiting for 'Return to Sender' or 'Special Handling' 
// (which have higher priority due to courier deadlines) are serviced before general campus delivery requests.

/* 
   Task 5: Parcel Category Organisation Module
   Author: [Student Name]
   Description: Using a Binary Search Tree (BST) to organize parcels by Parcel ID.
   Justification: BST allows O(log n) average time complexity for searching, inserting, and deleting records.
*/

#include <iostream>
#include <string>

struct Node {
    string parcelID;
    string category;
    Node *left, *right;
    Node(string id, string cat) : parcelID(id), category(cat), left(NULL), right(NULL) {}
};

class ParcelBST {
private:
    Node* root;

    Node* insert(Node* node, string id, string cat) {
        if (!node) return new Node(id, cat);
        if (id < node->parcelID) node->left = insert(node->left, id, cat);
        else if (id > node->parcelID) node->right = insert(node->right, id, cat);
        else cout << "Duplicate Key Exception\n";
        return node;
    }

    Node* findMin(Node* node) {
        while (node && node->left) node = node->left;
        return node;
    }

    Node* remove(Node* node, string id) {
        if (!node) return NULL;
        if (id < node->parcelID) node->left = remove(node->left, id);
        else if (id > node->parcelID) node->right = remove(node->right, id);
        else {
            if (!node->left) { Node* temp = node->right; delete node; return temp; }
            if (!node->right) { Node* temp = node->left; delete node; return temp; }
            Node* temp = findMin(node->right);
            node->parcelID = temp->parcelID;
            node->right = remove(node->right, temp->parcelID);
        }
        return node;
    }

    void inorder(Node* node) {
        if (!node) return;
        inorder(node->left);
        cout << "Parcel ID: " << node->parcelID << " | Category: " << node->category << endl;
        inorder(node->right);
    }

public:
    ParcelBST() : root(NULL) {}
    void add(string id, string cat) { root = insert(root, id, cat); }
    void del(string id) { root = remove(root, id); }
    void display() { if(!root) cout << "Empty tree.\n"; else inorder(root); }

    void search(string id) {
        Node* curr = root;
        while (curr) {
            if (curr->parcelID == id) { cout << "Found: " << curr->category << "\n"; return; }
            curr = (id < curr->parcelID) ? curr->left : curr->right;
        }
        cout << "Parcel " << id << " not found.\n";
    }
};

// Reflection: The BST is ideal for categorization because it naturally sorts the IDs.
// This makes generating sorted reports for the APU campus delivery centre very efficient compared to an unsorted array.
